def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    my_last, opp_last = history[-1]
    if n == 1:
        return 'C'
    # Score differential: punish exploiters, avoid over-defecting cooperators.
    my_score = 0
    opp_score = 0
    cc = cd = dc = dd = 0
    for m, o in history:
        if m == 'C' and o == 'C':
            my_score += 3
            opp_score += 3
            cc += 1
        elif m == 'C' and o == 'D':
            opp_score += 5
            cd += 1
        elif m == 'D' and o == 'C':
            my_score += 5
            dc += 1
        else:
            my_score += 1
            opp_score += 1
            dd += 1
    opp_def = cd + dd
    my_def = dc + dd
    # Endgame exploitation: when opponent is clearly cooperative, defect.
    if n >= 92:
        if opp_def * 4 <= n:
            return 'D'
        if opp_last == 'D':
            return 'D'
        if rng.random() < 0.5:
            return 'D'
        return 'C'
    # Strong retaliation against sustained defection.
    recent = history[-10:]
    r_opp_def = sum(1 for m, o in recent if o == 'D')
    if r_opp_def >= 8:
        return 'D'
    if r_opp_def >= 5 and opp_last == 'D':
        return 'D'
    # Pure cooperation if opponent essentially never defected.
    if opp_def == 0:
        if n >= 70 and rng.random() < 0.15:
            return 'D'
        return 'C'
    # Against mostly cooperative opponents, cooperate to maximize joint value.
    if r_opp_def <= 1:
        if opp_last == 'D':
            return 'D'
        return 'C'
    # Tit-for-tat core with forgiveness calibrated by opponent's defection rate.
    rate = opp_def / float(n)
    if opp_last == 'D':
        # Forgive rarely and only if we have been defecting too much.
        if my_def > opp_def + 2 and rng.random() < 0.3:
            return 'C'
        if rate < 0.2 and rng.random() < 0.25:
            return 'C'
        return 'D'
    # Opponent cooperated.
    if my_last == 'D':
        return 'C'
    if rate > 0.4:
        if rng.random() < 0.4:
            return 'D'
        return 'C'
    return 'C'
